SELECT ?a ?thing ?type ?ccy ?date ?action ?rating ?outlook ?watch ?comment WHERE {
  ?a a lad:RatingAction ; lad:ratedThing ?thing .
  OPTIONAL {?a lad:ratingType ?type}
  OPTIONAL {?a lad:ccyBasis ?ccy}
  OPTIONAL {?a lad:date ?date}
  OPTIONAL {?a lad:action ?action}
  OPTIONAL {?a lad:rating ?rating}
  OPTIONAL {?a lad:outlook ?outlook}
  OPTIONAL {?a lad:watch ?watch}
  OPTIONAL {?a lad:comment ?comment}
  FILTER(REGEX(STR(?thing), "/(I0[0-9]|E1[1-9]|E0[0-9]|E10)$") && !REGEX(STR(?thing), "/E0[1-9]$|/E10$"))
} ORDER BY ?thing ?type ?ccy ?date
