SELECT ?kind (GROUP_CONCAT(DISTINCT ?e; separator=",") AS ?ids) (COUNT(DISTINCT ?k) AS ?n) WHERE {
  ?a lad:ratedThing ?e ; lad:ratingType lad:type-LTIDR ; lad:date ?d ; lad:rating ?r .
  ?e a lad:Entity ; lad:sourceSystem ?s . FILTER(?s != "QA")
  OPTIONAL {?e lad:lei ?lei} OPTIONAL {?a lad:ccyBasis ?c} OPTIONAL {?a lad:outlook ?o} OPTIONAL {?a lad:watch ?w}
  FILTER(STR(?d) <= "2026-10-01")
  FILTER NOT EXISTS { ?b lad:ratedThing ?e ; lad:ratingType lad:type-LTIDR ; lad:date ?d2 .
    OPTIONAL{?b lad:ccyBasis ?c2} FILTER(COALESCE(STR(?c2),"")=COALESCE(STR(?c),"")) FILTER(STR(?d2) <= "2026-10-01" && STR(?d2) > STR(?d)) }
  BIND(COALESCE(?lei, STR(?e)) AS ?k)
  BIND(IF(?w = lad:watch-RWN, "RWN", IF(?o = lad:outlook-NEG, "NEG", "other")) AS ?kind)
  FILTER(?kind != "other")
} GROUP BY ?kind
